    """Write a case's setup files. Returns an error string if any path escapes."""
    for rel, content in (files or {}).items():
        if os.path.isabs(rel) or ".." in Path(rel).parts:
            return "setup file escapes workdir: %r" % rel
        target = workdir / rel
