"""Re-run every extracted pair myself: CPython x2 (determinism), lypning, lypning-l."""
from __future__ import annotations
import json, os, re, shutil, subprocess, sys, tempfile, collections
from pathlib import Path

SB = Path("/tmp/claude-0/-home-user-lypning/05e2ce2d-c800-5df6-a220-b3efcfe06b17/scratchpad/sb")
BIN = Path(os.path.expanduser("~/.lypning/bin"))
CPY = "/usr/bin/python3"
ABSPATH = re.compile(r"""["'](/(?:etc|usr|var|home|root|srv|opt|tmp|bin|sbin|proc|sys|dev)\b[^"']*)["']""")

def materialise(cwd, files):
    for name, content in (files or {}).items():
        p = cwd / name
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(content.encode("latin-1") if any(ord(c) > 127 for c in content)
                      else content.encode("utf-8"))

def run(prog, rec, engine, timeout=20.0):
    if engine == "cpython":
        argv = [CPY, "-c", prog]
    else:
        argv = [str(BIN / engine), "-c", prog]
    argv += [str(a) for a in (rec.get("argv") or [])]
    env = {"PATH": "/usr/bin:/bin", "HOME": os.environ.get("HOME", "/root"),
           "LC_ALL": "C.UTF-8", "LYPNING_HOME": os.path.expanduser("~/.lypning")}
    cwd = Path(tempfile.mkdtemp(prefix="sb-%s-" % engine, dir=str(SB / "tmp")))
    try:
        materialise(cwd, rec.get("files"))
        try:
            p = subprocess.run(argv, input=(rec.get("stdin") or "").encode("utf-8"),
                               cwd=str(cwd), env=env, stdout=subprocess.PIPE,
                               stderr=subprocess.PIPE, timeout=timeout)
        except subprocess.TimeoutExpired:
            return {"exit": -9, "stdout": "", "stderr": "timeout"}
        except OSError as e:
            return {"exit": -1, "stdout": "", "stderr": str(e)}
        return {"exit": p.returncode, "stdout": p.stdout.decode("utf-8", "replace"),
                "stderr": p.stderr.decode("utf-8", "replace")}
    finally:
        shutil.rmtree(cwd, ignore_errors=True)

def refused(r):
    """The exit-90 contract: exit 90, empty stdout, one unsupported line."""
    if r["exit"] != 90 or r["stdout"] != "":
        return None
    lines = [l for l in r["stderr"].strip().splitlines() if l.strip()]
    if len(lines) != 1 or ": unsupported: " not in lines[0]:
        return None
    return lines[0]

def main():
    (SB / "tmp").mkdir(parents=True, exist_ok=True)
    recs = [json.loads(l) for l in open(SB / "pairs.jsonl")]
    out = open(SB / "verified.jsonl", "w")
    n = 0
    for rec in recs:
        allowed = {str(a) for a in (rec.get("argv") or [])}
        hits = [m.group(1) for m in ABSPATH.finditer(rec["program"])]
        skip = next((h for h in hits if h not in allowed), None)
        v = {"pair_id": rec["pair_id"], "task_id": rec["task_id"],
             "recorded_tier1_win": rec["tier1_win"], "recorded_correct": rec["correct"],
             "abs_path_skip": skip}
        if skip:
            v["status"] = "skipped-abs-path"
        else:
            a = run(rec["program"], rec, "cpython")
            b = run(rec["program"], rec, "cpython")
            v["cpython_exit"] = a["exit"]
            v["cpython_deterministic"] = (a["stdout"] == b["stdout"] and a["exit"] == b["exit"])
            v["cpython_correct"] = bool(a["exit"] == 0 and a["stdout"] == rec["expect_stdout"])
            l1 = run(rec["program"], rec, "lypning")
            l2 = run(rec["program"], rec, "lypning-l")
            v["lypning_exit"] = l1["exit"]; v["lypning_l_exit"] = l2["exit"]
            v["lypning_refusal"] = refused(l1)
            v["lypning_l_refusal"] = refused(l2)
            v["refused_by_both"] = bool(v["lypning_refusal"] and v["lypning_l_refusal"])
            v["tier1_win"] = bool(l1["exit"] == 0 and l1["stdout"] == a["stdout"] and v["cpython_correct"])
            v["mismatch"] = bool(l1["exit"] == 0 and l1["stdout"] != a["stdout"])
            v["status"] = "ok"
        out.write(json.dumps(v, sort_keys=True) + "\n")
        n += 1
        if n % 50 == 0:
            print("...", n, file=sys.stderr, flush=True)
    out.close()
    print("verified", n)

main()

