def means_for(scores, resamples=RESAMPLES, seed=SEED):
    rng=random.Random(seed); n=len(scores); vals=list(scores)
    m=[sum(rng.choices(vals,k=n))/n for _ in range(resamples)]
    m.sort(); return m
def qi(m,p):
    h=p*(len(m)-1); lo=math.floor(h); hi=math.ceil(h)
    return m[lo]+(h-lo)*(m[hi]-m[lo])

