from __future__ import annotations
import json, io, keyword, builtins, tokenize, difflib, re

SAMPLE={o['id']:o for o in json.load(open('/tmp/bt/sample.json'))}
P=json.load(open('/tmp/bt/prompts.json'))
S=json.load(open('/tmp/bt/solutions.json'))
E=json.load(open('/tmp/bt/eval.json'))
BUILTIN=set(dir(builtins))|set(keyword.kwlist)

def pytokens(src):
    """Structural token stream: NAME/OP/NUMBER/STRING, names kept, strings as values."""
    out=[]
    try:
        for t in tokenize.generate_tokens(io.StringIO(src).readline):
            if t.type in (tokenize.NAME, tokenize.OP, tokenize.NUMBER, tokenize.STRING):
                out.append(t.string)
    except Exception:
        out=re.findall(r"\w+|[^\w\s]", src)
    return out

def payload(src):
    """The program's own choices: non-builtin identifiers + literal values."""
    ids=set(); lits=set()
    for t in pytokens(src):
        if re.match(r"^[A-Za-z_]\w*$", t):
            if t not in BUILTIN: ids.add(t)
        elif re.match(r"^['\"]", t) or re.match(r"^[\d.]", t):
            lits.add(t)
    return ids, lits

def frac_in(items, text):
    if not items: return None
    hit=sum(1 for i in items if i in text)
    return hit/len(items)

def unquote(lit):
    try:
        v=eval(lit, {"__builtins__":{}}, {})
        return str(v)
    except Exception:
        return lit

rows={}
for cid,o in SAMPLE.items():
    prompt=P[cid]; prog=o['program']; sol=S[cid]; exp=o['expect_stdout']
    # A: answer leakage - expected stdout lines that appear verbatim in the prompt
    lines=[l for l in dict.fromkeys(exp.split("\n")) if l.strip()]
    A=frac_in(lines, prompt)
    # B: program echo - program's own identifiers / literal values present in the prompt
    ids,lits=payload(prog)
    Bi=frac_in(ids, prompt)
    Bl=frac_in([unquote(l) for l in lits], prompt)
    # C: solution echo - token-sequence similarity blind solution vs original program
    C=difflib.SequenceMatcher(None, pytokens(prog), pytokens(sol)).ratio()
    rows[cid]={'A_answer_leak':A,'B_ident_leak':Bi,'B_literal_leak':Bl,'C_sol_echo':C,
               'kind':o['kind'],'correct':E[cid]['correct'],'passed':E[cid]['passed'],
               'plen':o['plen'],'n_exp_lines':len(lines)}
json.dump(rows, open('/tmp/bt/contam.json','w'), indent=1)

