    att=[json.loads(l) for l in open('runs/%s/attempts.jsonl'%run) if l.strip()]
    flag=collections.Counter(); cases=collections.defaultdict(set)
    for a in att:
        if not a.get('passed'): continue
        c=corpus[a['case_id']]
        why=looks_like_literal_output(a.get('program') or '', c['test'].get('expect_stdout',''))
        if why:
            flag[stratum(c['category'])]+=1
            cases[stratum(c['category'])].add(a['case_id'])
    npass=sum(1 for a in att if a.get('passed'))
    print(run,'passes',npass,'flagged-as-cheat',sum(flag.values()),flag, {k:len(v) for k,v in cases.items()})

