"""Recovery experiment for the `indexerror` unusable class.

Mirrors lypning.conformance.seed_files: the empty sandbox manufactures an
exception; we supply, mechanically, only the thing the sandbox removed, and
then let the ORIGINAL program under CPython define the expected answer.
Here the missing thing is not a file but the two inputs the capture harness
never recorded: argv and stdin.
"""
from __future__ import annotations
import ast, json, sys, os

sys.path.insert(0, '/home/user/lypning/nemotron')
sys.path.insert(0, '/home/user/lypning/src')

from pipeline import engines as eng
from pipeline.sandbox import run_python
from lypning import conformance as conf

# --- the seeds ------------------------------------------------------------
# One fixed blob, like conformance._SEED_DEFAULT. Values chosen so that a
# program reading "an int then a float" exercises every branch of what it
# computes: 90061 s is 1d 1h 1m 1s, so no field of a d/h/m/s split is zero and
# no product is a round number. A seed whose value is a fixed point of the
# computation would make the case guessable; this one does not.
SEED_STDIN = "90061 4.5\nalpha beta gamma\n"
SEED_DEFAULT = conf._SEED_DEFAULT           # repo's own bytes
SEED_CONTENT = conf._SEED_CONTENT


def argv_slots(program):
    """The integer subscripts of sys.argv the program names. None if it slices."""
    try:
        tree = ast.parse(program)
    except SyntaxError:
        return None
    slots, sliced = set(), False
    for n in ast.walk(tree):
        if not isinstance(n, ast.Subscript):
            continue
        v = n.value
        if not (isinstance(v, ast.Attribute) and v.attr == "argv"
                and isinstance(v.value, ast.Name) and v.value.id == "sys"):
            continue
        s = n.slice
        if isinstance(s, ast.Constant) and isinstance(s.value, int):
            slots.add(s.value)
        else:
            sliced = True
    if sliced and not slots:
        return None
    return slots


def reads_stdin(program):
    try:
        tree = ast.parse(program)
    except SyntaxError:
        return "sys.stdin" in program
    for n in ast.walk(tree):
        if isinstance(n, ast.Attribute) and n.attr == "stdin":
            return True
    return False


def json_parses_input(program):
    return "json.loads" in program or "json.load(" in program


def seed_inputs(program, variant):
    """(argv, stdin, files) or None. Mechanical; no per-entry tuning."""
    argv, stdin, files = None, None, {}
    if reads_stdin(program):
        stdin = SEED_STDIN
    slots = argv_slots(program)
    if slots:
        if variant == "stdin-only":
            return None if stdin is None else ([], stdin, {})
        n = max(slots)
        if n > 8:
            return None
        argv = []
        for i in range(1, n + 1):
            if variant == "argv-dir":
                name = "arg%d" % i
                files[name + "/.keep"] = ""
            elif variant == "argv-typed" and json_parses_input(program):
                name = "arg%d.jsonl" % i
                files[name] = SEED_CONTENT[".jsonl"].decode()
            else:
                name = "arg%d" % i
                files[name] = SEED_DEFAULT.decode()
            argv.append(name)
    if argv is None and stdin is None:
        return None
    return (argv or [], stdin, files)


def run(program, argv, stdin, files, binary, timeout_s=10.0):
    return run_python(program, argv=argv, stdin=stdin, files=files,
                      timeout_s=timeout_s,
                      interpreter=[binary] if binary else None)


def classify(program, entry, argv, stdin, files, timeout_s=10.0):
    """Faithful copy of lypning_source.classify_entry, plus `files`."""
    a = [str(x) for x in argv]
    if conf.is_nondeterministic(entry):
        return "skip", {"reason": "nondeterministic"}
    battery = conf.spawns_a_battery(program)
    if battery:
        return "skip", {"reason": battery}
    outside = conf.absolute_paths(program)
    for x in a:
        outside.extend(p for p in conf.absolute_paths(x) if p not in outside)
    if outside:
        return "skip", {"reason": "absolute path: %s" % outside[0]}
    ref = run(program, a, stdin, files, None, timeout_s)
    if ref.harness_error:
        return "skip", {"reason": "harness: %s" % ref.harness_error}
    if ref.timed_out or ref.exit_code != 0 or not ref.stdout.strip():
        return "unusable", {"reason": "CPython gives no clean answer: %s" % ref.brief(160)}
    r = None
    for name in eng.DEFAULT_CHAIN:
        b = eng.engine_path(name)
        r = run(program, a, stdin, files, b, timeout_s)
        if r.harness_error:
            return "skip", {"reason": "harness: %s" % r.harness_error}
        if r.exit_code != eng.REFUSAL_EXIT:
            if r.stdout != ref.stdout or r.exit_code != ref.exit_code:
                return "skip", {"reason": "MISMATCH on %s: %s" % (name, r.brief(120))}
            return "tier1", {"engine": name}
    parsed = eng.parse_refusal(r.stderr)
    if not parsed:
        return "skip", {"reason": "exit 90 without a refusal line"}
    _, kind, detail = parsed
    return "refused", {"kind": kind, "detail": detail,
                       "expect_stdout": ref.stdout, "expect_exit": ref.exit_code}

